    const value = ref.slice("commit:".length).trim();
    if (value === "") continue;
    const full = [...commits].find((commit) => commit.startsWith(value));
    commits.add(full ?? value);
  }
  return Object.freeze([...commits]);
}

/** Compare a recorded commit (possibly abbreviated) with an accepted full commit. */
export function commitReferenceMatches(recorded: string, accepted: string): boolean {
  if (recorded === accepted) return true;
  if (recorded.length < 7 || accepted.length < 7) return false;
  return accepted.startsWith(recorded) || recorded.startsWith(accepted);
}

